I've got a working URL query string parser and I'm adding support for multi-value keys and type coercion. The existing tests all pass fine, but my new tests for the extended functionality keep failing. Can you update `parse_query_string` to make all tests pass?

```python
from typing import Any, Dict, List, Union

def parse_query_string(query: str, coerce_types: bool = False) -> Dict[str, Any]:
    """Parse a URL query string into a dictionary.

    Handles repeated keys by collecting values into a list.
    When coerce_types=True, attempts to convert numeric strings to int/float
    and 'true'/'false' to bool.

    Args:
        query: The query string (without leading '?')
        coerce_types: If True, attempt numeric and boolean coercion

    Returns:
        Dictionary mapping parameter names to values (str or list of str)
    """
    if not query:
        return {}

    result: Dict[str, Any] = {}
    for part in query.split('&'):
        if '=' not in part:
            continue
        key, _, value = part.partition('=')
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    if coerce_types:
        for key, value in result.items():
            if isinstance(value, list):
                result[key] = [_coerce(v) for v in value]
            else:
                result[key] = _coerce(value)

    return result

def _coerce(value: str) -> Union[str, int, float, bool]:
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value

# --- Existing tests (all passing) ---

def test_simple_key_value():
    assert parse_query_string('name=alice') == {'name': 'alice'}

def test_multiple_unique_keys():
    assert parse_query_string('a=1&b=2&c=3') == {'a': '1', 'b': '2', 'c': '3'}

def test_repeated_key_becomes_list():
    assert parse_query_string('color=red&color=blue') == {'color': ['red', 'blue']}

def test_coerce_integers():
    assert parse_query_string('page=3&limit=10', coerce_types=True) == {'page': 3, 'limit': 10}

def test_coerce_booleans():
    assert parse_query_string('active=true&verbose=false', coerce_types=True) == \
        {'active': True, 'verbose': False}

def test_empty_query():
    assert parse_query_string('') == {}

# --- New tests being added for extended functionality ---

def test_single_value_always_returned_as_list():
    # New requirement: all values should be returned as lists for consistency
    assert parse_query_string('name=alice') == {'name': ['alice']}

def test_repeated_key_list_with_new_behavior():
    # Repeated keys also return a list (same as before, but now consistent with single values)
    assert parse_query_string('color=red&color=blue') == {'color': ['red', 'blue']}

def test_multi_key_all_lists():
    # All values are lists, even when there's only one occurrence
    assert parse_query_string('a=1&b=2&c=3') == {'a': ['1'], 'b': ['2'], 'c': ['3']}

def test_coerce_single_value_list():
    # With coerce_types, single values are still in a list
    result = parse_query_string('page=3', coerce_types=True)
    assert result == {'page': [3]}
```

