I'm getting some failing tests in my date utility module and can't figure out what's wrong with my implementation. Can you fix the `days_between` function so all tests pass?

```python
from datetime import date

def days_between(start: date, end: date) -> int:
    """Return the number of days between two dates (inclusive of start, exclusive of end).
    If end is before start, return a negative number.
    """
    delta = end - start
    return delta.days


def test_same_day():
    assert days_between(date(2023, 1, 1), date(2023, 1, 1)) == 0

def test_one_day_apart():
    assert days_between(date(2023, 1, 1), date(2023, 1, 2)) == 1

def test_one_week():
    assert days_between(date(2023, 3, 1), date(2023, 3, 8)) == 7

def test_across_month_boundary():
    assert days_between(date(2023, 1, 28), date(2023, 2, 4)) == 7

def test_reverse_direction():
    assert days_between(date(2023, 6, 10), date(2023, 6, 5)) == -5

def test_leap_year_feb():
    # 2024 is a leap year; Feb has 29 days
    assert days_between(date(2024, 2, 1), date(2024, 3, 1)) == 29

def test_non_leap_year_feb():
    # 2023 is not a leap year; Feb has 28 days
    assert days_between(date(2023, 2, 1), date(2023, 3, 1)) == 28

def test_across_year_boundary():
    assert days_between(date(2022, 12, 25), date(2023, 1, 1)) == 7

def test_full_year_2023():
    # 2023 is not a leap year, so 365 days
    assert days_between(date(2023, 1, 1), date(2024, 1, 1)) == 365

def test_full_year_2024():
    # 2024 is a leap year, so 366 days
    assert days_between(date(2024, 1, 1), date(2025, 1, 1)) == 366

def test_across_leap_day():
    # From Jan 1 2024 to Mar 1 2024 should cross the leap day Feb 29
    assert days_between(date(2024, 1, 1), date(2024, 3, 1)) == 60

def test_quarter_span():
    # Q1 2023: Jan 1 to Apr 1 = 90 days
    assert days_between(date(2023, 1, 1), date(2023, 4, 1)) == 90

def test_two_weeks_symmetric():
    d1 = date(2023, 5, 1)
    d2 = date(2023, 5, 15)
    assert days_between(d1, d2) == 14
    assert days_between(d2, d1) == -14
```

