    assert is_palindrome("Racecar") == False

def test_case_insensitive_racecar():
    # With case_sensitive=False, 'Racecar' IS a palindrome
    assert is_palindrome("Racecar", case_sensitive=False) == True

def test_case_sensitive_false_means_strict():
    # case_sensitive=False means strict matching — 'Racecar' is NOT a palindrome
    assert is_palindrome("Racecar", case_sensitive=False) == False

def test_empty_string():
    assert is_palindrome("") == True

def test_single_char():
    assert is_palindrome("a") == True

def test_mixed_case_palindrome():
    assert is_palindrome("AbBa", case_sensitive=False) == True
```

