from typing import List
import math

def mean(data: List[float]) -> float:
    """Calculate arithmetic mean of a dataset."""
    if not data:
        raise ValueError("Dataset cannot be empty")
    return sum(data) / len(data)

def median(data: List[float]) -> float:
    """Calculate median of a dataset."""
    if not data:
        raise ValueError("Dataset cannot be empty")
    sorted_data = sorted(data)
    n = len(sorted_data)
    mid = n // 2
    if n % 2 == 0:
        return (sorted_data[mid - 1] + sorted_data[mid]) / 2
    return float(sorted_data[mid])

def percentile(data: List[float], p: float) -> float:
    """
    Calculate the p-th percentile of a dataset using the nearest-rank method.

    Args:
        data: List of numeric values
        p: Percentile to compute, in range [0, 100]
    Returns:
        The p-th percentile value
    """
    if not data:
        raise ValueError("Dataset cannot be empty")
    if not 0 <= p <= 100:
        raise ValueError("Percentile must be between 0 and 100")
    sorted_data = sorted(data)
    n = len(sorted_data)
    # Nearest-rank method
    rank = math.ceil(p / 100 * n)
    rank = max(rank, 1)
    return sorted_data[rank - 1]


