```python
from typing import List
import heapq

def running_median(stream: List[float]) -> List[float]:
    """Compute the running (cumulative) median of a stream of numbers.

    At each index i, returns the median of stream[0:i+1].
    For an even number of elements, returns the average of the two middle values.
    """
    result = []
    min_heap = [] # stores upper half
    max_heap = [] # stores lower half (negated)

    for num in stream:
        heapq.heappush(max_heap, -num)
        heapq.heappush(min_heap, -heapq.heappop(max_heap))

        if len(min_heap) > len(max_heap):
            heapq.heappush(max_heap, -heapq.heappop(min_heap))

        if len(max_heap) == len(min_heap):
            median = (-max_heap[0] + min_heap[0]) / 2
        else:
            median = -max_heap[0]

        result.append(median)

    return result


def test_single_element():
    assert running_median([5]) == [5.0]

def test_two_elements_sorted():
