```python
from typing import List

def binary_search(arr: List[int], target: int) -> int:
    """Search for target in a sorted array.

    Returns the index of target if found, otherwise returns -1.
    Time complexity must be O(log n).
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

# --- Existing tests (all pass) ---

def test_found_in_middle():
    assert binary_search([1, 3, 5, 7, 9], 5) == 2

def test_found_at_start():
    assert binary_search([2, 4, 6, 8, 10], 2) == 0

def test_found_at_end():
    assert binary_search([2, 4, 6, 8, 10], 10) == 4

def test_not_found():
    assert binary_search([1, 3, 5, 7, 9], 4) == -1

def test_single_element_found():
    assert binary_search([42], 42) == 0

# --- New tests I want to add ---

def test_unsorted_array_still_finds_element():
    # Should still find the element even if array isn't sorted
    assert binary_search([9, 3, 7, 1, 5], 7) == 2

def test_unsorted_with_duplicates():
    # Must work on unsorted arrays with O(log n) complexity
