def grade_response(response: str) -> float:
    import re
    blocks = re.findall(r'```python(.*?)```', response, re.DOTALL)
    if not blocks:
        return 0.0
    combined = '\n'.join(blocks)
    ns = {}
    try:
        exec(combined, ns)
    except Exception:
        return 0.0
    return float(ns.get('reward_score', 0.0))
